import * as XLSX from 'xlsx';

const LOCATIONS = { SC: 'Santa Clara', F: 'Fremont', WC: 'Walnut Creek', SV: 'Sunnyvale' };

// Optomap monthly costs per location
export const OPTOMAP_COSTS = { SC: 1801.65 + 52.95, F: 1820.23, WC: 1628.92, SV: 1641.24 };

function levenshtein(a, b) {
  const m = a.length, n = b.length;
  const dp = Array.from({ length: m + 1 }, (_, i) =>
    Array.from({ length: n + 1 }, (_, j) => i === 0 ? j : j === 0 ? i : 0));
  for (let i = 1; i <= m; i++)
    for (let j = 1; j <= n; j++)
      dp[i][j] = a[i-1] === b[j-1] ? dp[i-1][j-1] : 1 + Math.min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]);
  return dp[m][n];
}

const PAYOR_EXACT = {
  'EM': 'EyeMed', 'EYEMED': 'EyeMed', 'AETNA': 'EyeMed', 'AETNA DISC': 'EyeMed', 'CIGNA': 'EyeMed', 'CIG': 'EyeMed',
  'VSP': 'VSP', 'VPS': 'VSP', 'METLIFE': 'VSP', 'MET LIFE': 'VSP', 'METLIFE VISION': 'VSP', 'GUARDIAN': 'VSP', 'GUARDIAN VISION': 'VSP',
  'UHC': 'UHC', 'UNITED': 'UHC', 'UNITED HEALTHCARE': 'UHC', 'SPECTERA': 'UHC',
  'SUPERIOR': 'Superior', 'SUP': 'Superior', 'SUOERIOR': 'Superior', 'SUPERIO': 'Superior', 'SUPERIOE': 'Superior',
  'DAVIS': 'Davis', 'DAVIS VISION': 'Davis',
  'COLONIAL': 'Colonial', 'COLORIAL': 'Colonial', 'COLONAIL': 'Colonial',
  'FEP': 'FEP', 'NVA': 'NVA', 'VBA': 'VBA', 'AVESIS': 'Avesis', 'HERITAGE': 'Heritage',
  'SELF': 'Self Pay', 'CASH': 'Self Pay', 'OOP': 'Self Pay',
};

const FUZZY_RULES = [
  ['Superior', 'SUPERIOR', 2],
  ['Colonial', 'COLONIAL', 2],
  ['EyeMed',   'EYEMED',   2],
  ['Davis',    'DAVIS',    2],
];

function normalizePayor(p) {
  if (!p) return 'Self Pay';
  const up = String(p).trim().toUpperCase();
  if (!up) return 'Self Pay';
  if (PAYOR_EXACT[up]) return PAYOR_EXACT[up];
  for (const [canonical, target, maxDist] of FUZZY_RULES) {
    if (Math.abs(up.length - target.length) <= maxDist && levenshtein(up, target) <= maxDist)
      return canonical;
  }
  return p;
}

export function getPayorCategory(payor) {
  return payor === 'Self Pay' ? 'Self Pay' : 'Insurance';
}

function inferMyopiaType(amount) {
  if (!amount || amount <= 1) return null;
  if (amount >= 1800) return 'Ortho-K (New)';
  if (amount >= 1100) return 'Ortho-K (Return)';
  if (amount >= 550)  return 'MiSight (New)';
  if (amount >= 350)  return 'MiSight (Return)';
  if (amount >= 280)  return 'Atropine/Stellest (New)';
  if (amount >= 150)  return 'Atropine/Stellest (Return)';
  return 'Myopia Control (Other)';
}

function getISOWeek(date) {
  const d = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()));
  d.setUTCDate(d.getUTCDate() + 4 - (d.getUTCDay() || 7));
  const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
  return Math.ceil((((d - yearStart) / 86400000) + 1) / 7);
}

function parseSheet(ws, year) {
  const rows = XLSX.utils.sheet_to_json(ws, { header: 1, defval: null });
  let headerIdx = rows.findIndex(r => r && r[0] === 'Location' && r[6] === 'Doctor');
  if (headerIdx === -1) headerIdx = 0;

  const headers = rows[headerIdx].map(h => h ? String(h).trim() : '');
  const col = (name) => headers.indexOf(name);

  const iLocation  = col('Location');
  const iDay       = col('Day');
  const iDate      = col('Date');
  const iStatus    = col('Status');
  const iDoctor    = col('Doctor');
  const iGross     = col('Gross');
  const iPatient   = col('Patient Name');
  const iRoutine   = col('Routine');
  const iCL        = col('CL');
  const iOptos     = col('Optos');
  const iDFE       = col('DFE');
  const iOV        = col('OV');
  const iOCT       = col('OCT');
  const iTopo      = col('Topo');
  const iOther     = col('Other');
  const iMyopia    = col('Myopia');
  const iLASIK     = col('LASIK');
  const iMaterials = col('Materials');
  const iPaid      = col('Paid');
  const iIns       = col('Ins');
  const iPayor     = col('Payor');
  const iPayor2    = col('Payor 2');
  const iCash      = col('Cash');
  const iInsPaid   = col('Insurance Paid');
  const iPayErr    = col('Payment Error Loss');
  const iInsNon    = col('Insurance Nonpayment Loss');
  const iWeek      = col('Week');

  const patients = [];
  let currentDoctorDayKey = null;
  let currentGross = null;

  for (let i = headerIdx + 1; i < rows.length; i++) {
    const r = rows[i];
    if (!r) continue;

    const loc    = r[iLocation] ? String(r[iLocation]).trim() : null;
    const doctor = r[iDoctor]   ? String(r[iDoctor]).trim()   : null;
    const patient= r[iPatient]  ? String(r[iPatient]).trim()  : null;

    if (!loc || !LOCATIONS[loc]) continue;
    if (doctor === 'CLOSED' || !doctor) continue;
    if (!patient || patient === 'Patient Name') continue;
    if (patient.includes('/') || (patient.toUpperCase() === patient && patient.length < 10)) continue;

    let dateVal = r[iDate];
    let jsDate = null;
    if (dateVal instanceof Date) {
      jsDate = dateVal;
    } else if (typeof dateVal === 'number') {
      const d = XLSX.SSF.parse_date_code(dateVal);
      if (d) jsDate = new Date(d.y, d.m - 1, d.d);
    } else if (typeof dateVal === 'string' && dateVal) {
      jsDate = new Date(dateVal);
    }
    if (!jsDate || isNaN(jsDate)) continue;

    const rowYear = jsDate.getFullYear();
    if (rowYear < 2023 || rowYear > 2027) continue;

    const dateStr   = jsDate.toISOString().split('T')[0];
    const month     = jsDate.getMonth() + 1;
    const isoWeek   = getISOWeek(jsDate);
    const dayOfWeek = r[iDay] ? String(r[iDay]).trim()
      : ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][jsDate.getDay()];

    const key = `${loc}-${doctor}-${dateStr}`;
    if (r[iGross] != null && r[iGross] !== '') {
      currentGross = parseFloat(r[iGross]) || 0;
      currentDoctorDayKey = key;
    }
    const grossForDay = currentDoctorDayKey === key ? currentGross : null;

    const paid         = parseFloat(r[iPaid])      || 0;
    const ins          = parseFloat(r[iIns])       || 0;
    const myopiaAmt    = parseFloat(r[iMyopia])    || 0;
    const lasikAmt     = parseFloat(r[iLASIK])     || 0;
    const materialsAmt = parseFloat(r[iMaterials]) || 0;
    const cash         = parseFloat(r[iCash])      || 0;
    const insPaid      = parseFloat(r[iInsPaid])   || 0;

    // Incomplete: both cash and insurance paid are blank (billing not entered)
    const rawCash    = r[iCash];
    const rawInsPaid = r[iInsPaid];
    const isPaidUnknown = (rawCash == null || rawCash === '') &&
                          (rawInsPaid == null || rawInsPaid === '');

    patients.push({
      year: rowYear,
      loc, locationName: LOCATIONS[loc],
      doctor, date: dateStr, month, isoWeek, dayOfWeek,
      patient,
      status: r[iStatus] ? String(r[iStatus]).trim() : null,
      routine: !!r[iRoutine], cl: !!r[iCL], optos: !!r[iOptos],
      dfe: !!r[iDFE], ov: !!r[iOV], oct: !!r[iOCT],
      topo: !!r[iTopo], other: !!r[iOther],
      hasMyopia: myopiaAmt > 1, myopiaAmt,
      myopiaType: inferMyopiaType(myopiaAmt),
      hasLASIK: lasikAmt > 0, lasikAmt, materialsAmt,
      paid, ins, total: paid + ins,
      payor: normalizePayor(r[iPayor]),
      payor2: r[iPayor2] ? normalizePayor(r[iPayor2]) : null,
      cash, insPaid,
      payErr: parseFloat(r[iPayErr]) || 0,
      insNon: parseFloat(r[iInsNon]) || 0,
      grossForDay, isPaidUnknown,
    });
  }
  return patients;
}

export function parseExcelFile(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const wb = XLSX.read(e.target.result, { type: 'array', cellDates: true });
        const results = { patients2026: [], patients2025: [], patients2024: [] };
        if (wb.SheetNames.includes('2026')) results.patients2026 = parseSheet(wb.Sheets['2026'], 2026);
        if (wb.SheetNames.includes('2025')) results.patients2025 = parseSheet(wb.Sheets['2025'], 2025);
        if (wb.SheetNames.includes('2024')) results.patients2024 = parseSheet(wb.Sheets['2024'], 2024);
        resolve(results);
      } catch (err) { reject(err); }
    };
    reader.onerror = reject;
    reader.readAsArrayBuffer(file);
  });
}

export function computeStats(patients, comparePatients = null) {
  if (!patients || patients.length === 0) return null;

  // For YoY: find latest MM-DD in current set, cap comparison to same point
  const maxDate  = patients.reduce((m, p) => p.date > m ? p.date : m, '');
  const maxMMDD  = maxDate.slice(5);
  const compareSamePeriod = comparePatients
    ? comparePatients.filter(p => p.date.slice(5) <= maxMMDD)
    : null;

  const total        = patients.length;
  const totalRevenue = patients.reduce((s, p) => s + p.total, 0);
  const totalPaid    = patients.reduce((s, p) => s + p.paid,  0);
  const totalIns     = patients.reduce((s, p) => s + p.ins,   0);

  // ── By Location ──────────────────────────────────────────────────────────
  const byLocation = {};
  for (const loc of Object.keys(LOCATIONS)) {
    const lp = patients.filter(p => p.loc === loc);
    const uniqueLocDays = [...new Set(lp.map(p => p.date))];
    byLocation[loc] = {
      name: LOCATIONS[loc],
      patients: lp.length,
      revenue:  lp.reduce((s, p) => s + p.total, 0),
      paid:     lp.reduce((s, p) => s + p.paid,  0),
      ins:      lp.reduce((s, p) => s + p.ins,   0),
      openDays: uniqueLocDays.length,
      revPerOpenDay: uniqueLocDays.length ? lp.reduce((s, p) => s + p.total, 0) / uniqueLocDays.length : 0,
      patientsPerOpenDay: uniqueLocDays.length ? lp.length / uniqueLocDays.length : 0,
      optos:    lp.filter(p => p.optos).length,
      optosRate: lp.length ? lp.filter(p => p.optos).length / lp.length : 0,
      oct:      lp.filter(p => p.oct).length,
      octRate:  lp.length ? lp.filter(p => p.oct).length / lp.length : 0,
      cl:       lp.filter(p => p.cl).length,
      clRate:   lp.length ? lp.filter(p => p.cl).length / lp.length : 0,
      myopia:   lp.filter(p => p.hasMyopia).length,
      myopiaRevenue: lp.reduce((s, p) => s + p.myopiaAmt, 0),
      avgPerPatient: lp.length ? lp.reduce((s, p) => s + p.total, 0) / lp.length : 0,
    };
  }

  // ── By Doctor ────────────────────────────────────────────────────────────
  const doctorNames = [...new Set(patients.map(p => p.doctor))].filter(d => d && d !== 'CLOSED');
  const byDoctor = {};
  for (const doc of doctorNames) {
    const dp = patients.filter(p => p.doctor === doc);
    const days = [...new Set(dp.map(p => p.date + p.loc))];
    const routineCount = dp.filter(p => p.routine).length;
    byDoctor[doc] = {
      patients: dp.length,
      revenue:  dp.reduce((s, p) => s + p.total, 0),
      optos: dp.filter(p => p.optos).length,
      oct:   dp.filter(p => p.oct).length,
      cl:    dp.filter(p => p.cl).length,
      myopia: dp.filter(p => p.hasMyopia).length,
      myopiaRevenue: dp.reduce((s, p) => s + p.myopiaAmt, 0),
      daysWorked: days.length,
      avgPerDay: days.length ? dp.reduce((s, p) => s + p.total, 0) / days.length : 0,
      avgPatientsPerDay: days.length ? dp.length / days.length : 0,
      avgPerPatient: dp.length ? dp.reduce((s, p) => s + p.total, 0) / dp.length : 0,
      avgPerRoutine: routineCount ? dp.reduce((s, p) => s + p.total, 0) / routineCount : 0,
      optosRate: dp.length ? dp.filter(p => p.optos).length / dp.length : 0,
      octRate:   dp.length ? dp.filter(p => p.oct).length / dp.length : 0,
      routineCount,
    };
  }

  // ── By Month ─────────────────────────────────────────────────────────────
  const byMonth = {};
  for (let m = 1; m <= 12; m++) {
    const mp = patients.filter(p => p.month === m);
    if (mp.length === 0) continue;
    const uniqueMonthDays = [...new Set(mp.map(p => p.date + p.loc))];
    byMonth[m] = {
      patients: mp.length,
      revenue:  mp.reduce((s, p) => s + p.total, 0),
      optos:    mp.filter(p => p.optos).length,
      oct:      mp.filter(p => p.oct).length,
      cl:       mp.filter(p => p.cl).length,
      myopia:   mp.filter(p => p.hasMyopia).length,
      myopiaRevenue: mp.reduce((s, p) => s + p.myopiaAmt, 0),
      openDays: uniqueMonthDays.length,
      byLoc: Object.fromEntries(Object.keys(LOCATIONS).map(loc => {
        const lmp = mp.filter(p => p.loc === loc);
        return [loc, {
          revenue: lmp.reduce((s, p) => s + p.total, 0),
          patients: lmp.length,
          optos: lmp.filter(p => p.optos).length,
          oct:   lmp.filter(p => p.oct).length,
        }];
      })),
    };
  }

  // ── By Week ──────────────────────────────────────────────────────────────
  const byWeek = {};
  for (const p of patients) {
    const wk = `${p.year}-W${String(p.isoWeek).padStart(2,'0')}`;
    if (!byWeek[wk]) byWeek[wk] = {
      week: wk, year: p.year, isoWeek: p.isoWeek,
      patients: 0, revenue: 0, optos: 0, oct: 0, cl: 0,
      byLoc: {
        SC: { revenue:0, patients:0, optos:0, oct:0 },
        F:  { revenue:0, patients:0, optos:0, oct:0 },
        WC: { revenue:0, patients:0, optos:0, oct:0 },
        SV: { revenue:0, patients:0, optos:0, oct:0 },
      },
    };
    byWeek[wk].patients++;
    byWeek[wk].revenue += p.total;
    byWeek[wk].optos   += p.optos ? 1 : 0;
    byWeek[wk].oct     += p.oct   ? 1 : 0;
    byWeek[wk].cl      += p.cl    ? 1 : 0;
    if (byWeek[wk].byLoc[p.loc]) {
      byWeek[wk].byLoc[p.loc].revenue  += p.total;
      byWeek[wk].byLoc[p.loc].patients += 1;
      byWeek[wk].byLoc[p.loc].optos    += p.optos ? 1 : 0;
      byWeek[wk].byLoc[p.loc].oct      += p.oct   ? 1 : 0;
    }
  }

  // ── By Day of Week ────────────────────────────────────────────────────────
  const byDay = {};
  for (const day of ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday']) {
    const dp = patients.filter(p => p.dayOfWeek === day);
    if (dp.length === 0) continue;
    const uniqueLocDays = [...new Set(dp.map(p => p.date + p.loc))];
    byDay[day] = {
      patients:   dp.length,
      revenue:    dp.reduce((s, p) => s + p.total, 0),
      occurrences: uniqueLocDays.length,
      avgPatients: uniqueLocDays.length ? dp.length / uniqueLocDays.length : 0,
      avgRevenue:  uniqueLocDays.length ? dp.reduce((s, p) => s + p.total, 0) / uniqueLocDays.length : 0,
    };
  }

  // ── Payor Mix ─────────────────────────────────────────────────────────────
  const payorCounts = {};
  for (const p of patients) {
    const pay = p.payor || 'Unknown';
    if (!payorCounts[pay]) payorCounts[pay] = { count: 0, revenue: 0 };
    payorCounts[pay].count++;
    payorCounts[pay].revenue += p.total;
  }
  for (const k of Object.keys(payorCounts))
    payorCounts[k].pct = patients.length ? payorCounts[k].count / patients.length : 0;

  // ── Myopia ────────────────────────────────────────────────────────────────
  const myopiaPatients = patients.filter(p => p.hasMyopia);
  const myopiaByType = {};
  for (const mp of myopiaPatients) {
    const t = mp.myopiaType || 'Unknown';
    if (!myopiaByType[t]) myopiaByType[t] = { count: 0, revenue: 0 };
    myopiaByType[t].count++;
    myopiaByType[t].revenue += mp.myopiaAmt;
  }

  // ── Optomap ROI ───────────────────────────────────────────────────────────
  const optomapROI = {};
  for (const loc of Object.keys(LOCATIONS)) {
    const lp = patients.filter(p => p.loc === loc);
    const months = [...new Set(lp.map(p => p.month))];
    const optosCount = lp.filter(p => p.optos).length;
    const monthlyCost = OPTOMAP_COSTS[loc] || 0;
    const monthsActive = months.length || 1;
    const totalCost = monthlyCost * monthsActive;
    const avgRev = lp.length ? lp.reduce((s, p) => s + p.total, 0) / lp.length : 0;
    const estOptosRevenue = optosCount * avgRev * 0.15;
    // Monthly breakdown for expandable rows
    const monthlyOptos = {};
    for (const p of lp) {
      if (!monthlyOptos[p.month]) monthlyOptos[p.month] = { optos: 0, revenue: 0, patients: 0 };
      monthlyOptos[p.month].patients++;
      if (p.optos) monthlyOptos[p.month].optos++;
      monthlyOptos[p.month].revenue += p.total;
    }
    const monthlyOptosArr = Object.entries(monthlyOptos)
      .sort(([a],[b]) => a - b)
      .map(([month, d]) => {
        const avgR = d.patients ? d.revenue / d.patients : 0;
        const estRev = d.optos * avgR * 0.15;
        return { month: parseInt(month), optos: d.optos, estRev, netROI: estRev - monthlyCost };
      });

    optomapROI[loc] = {
      optosCount, monthlyCost, monthsActive, totalCost,
      estOptosRevenue,
      netROI: estOptosRevenue - totalCost,
      breakEvenPerMonth: monthlyCost > 0 ? Math.ceil(monthlyCost / (avgRev * 0.15 || 1)) : 0,
      avgPerMonth: monthsActive ? Math.round(optosCount / monthsActive) : 0,
      monthlyOptosArr,
    };
  }

  // ── Incomplete Days ───────────────────────────────────────────────────────
  const dayGroups = {};
  for (const p of patients) {
    const k = `${p.loc}|${p.date}`;
    if (!dayGroups[k]) dayGroups[k] = { loc: p.loc, date: p.date, doctor: p.doctor, total: 0, unknown: 0 };
    dayGroups[k].total++;
    if (p.isPaidUnknown) dayGroups[k].unknown++;
  }
  const incompleteDays = Object.values(dayGroups)
    .filter(d => d.total > 0 && d.unknown / d.total > 0.5)
    .sort((a, b) => b.date.localeCompare(a.date))
    .slice(0, 30);

  // ── Prev period stats ─────────────────────────────────────────────────────
  const prevStats = compareSamePeriod && compareSamePeriod.length > 0
    ? computeStats(compareSamePeriod) : null;

  const uniqueDays = [...new Set(patients.map(p => p.date + p.loc))];

  return {
    total, totalRevenue, totalPaid, totalIns,
    uniqueDays: uniqueDays.length,
    avgRevenuePerDay: uniqueDays.length ? totalRevenue / uniqueDays.length : 0,
    avgPatientsPerDay: uniqueDays.length ? total / uniqueDays.length : 0,
    avgRevenuePerPatient: total ? totalRevenue / total : 0,
    byLocation, byDoctor, byMonth, byWeek, byDay,
    myopiaCount: myopiaPatients.length,
    myopiaRevenue: myopiaPatients.reduce((s, p) => s + p.myopiaAmt, 0),
    myopiaByType, payorCounts,
    optos: patients.filter(p => p.optos).length,
    oct:   patients.filter(p => p.oct).length,
    cl:    patients.filter(p => p.cl).length,
    lasik: patients.filter(p => p.hasLASIK).length,
    lasikRevenue: patients.reduce((s, p) => s + p.lasikAmt, 0),
    optomapROI, incompleteDays, maxDate, prevStats,
  };
}

export const LOCATION_NAMES = LOCATIONS;
export const MONTH_NAMES    = ['','Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
export const DOCTOR_LIST    = ['Kha','Pan','Fan','Ghag','Kaneta','Yang','Luong','Zhang','Burger','Cheng','Miranda','Pham','Duong','So'];
